| &lt;IN: &quot;in&quot; | &quot;IN&quot; | &quot;In&quot; | &quot;iN&quot;&gt;
| &lt;BETWEEN: (&quot;B&quot; | &quot;b&quot;) (&quot;E&quot; | &quot;e&quot;) (&quot;T&quot; | &quot;t&quot;) (&quot;W&quot; | &quot;w&quot;) (&quot;E&quot; | &quot;e&quot;) (&quot;E&quot; | &quot;e&quot;) (&quot;N&quot; | &quot;n&quot;)&gt;
| &lt;CONTAINS: (&quot;C&quot; | &quot;c&quot;) (&quot;O&quot; | &quot;o&quot;) (&quot;N&quot; | &quot;n&quot;) (&quot;T&quot; | &quot;t&quot;) (&quot;A&quot; | &quot;a&quot;) (&quot;I&quot; | &quot;i&quot;) (&quot;N&quot; | &quot;n&quot;) (&quot;S&quot; | &quot;s&quot;)&gt;
