| &lt;MATCHES: (&quot;M&quot; | &quot;m&quot;) (&quot;A&quot; | &quot;a&quot;) (&quot;T&quot; | &quot;t&quot;) (&quot;C&quot; | &quot;c&quot;) (&quot;H&quot; | &quot;h&quot;) (&quot;E&quot; | &quot;e&quot;) (&quot;S&quot; | &quot;s&quot;)&gt;
