| &lt;#LETTER: [| &lt;#PART_LETTER: [&quot;0&quot;-&quot;9&quot;,&quot;A&quot;-&quot;Z&quot;,&quot;_&quot;,&quot;a&quot;-&quot;z&quot;](&quot;A&quot;-&quot;Z&quot;,&quot;_&quot;,&quot;a&quot;-&quot;z&quot;]&gt;.md)&gt;
